//! Golden test of the protected helpers of `StructurePiece` (`placeBlock`, `generateBox`, `generateMaybeBox`,
//! `generateAirBox`, upper half sphere, `fillColumnDown`, `createChest`/`createDispenser`, `BlockSelector`) and the
//! ground-height helpers of `ScatteredFeaturePiece` against the real vanilla classes: random scripts over the synthetic
//! terrain (fixture `tests/fixtures/structure_piece.txt`, generated by `tests/oracle/StructurePieceOracle.java`). Every
//! `>` operation is replayed and compared with its `=` line, then the dump of all chunks is compared line by line.

mod common;

use common::feature_harness::*;
use mc_core::bounding_box::BoundingBox;
use mc_core::direction::Direction;
use mc_core::mirror::Mirror;
use mc_core::random::{LegacyRandomSource, RandomSource, WorldgenRandom};
use mc_core::rotation::Rotation;
use mc_data::block::BlockState;
use mc_game::world::level::levelgen::gen_level::GenLevel;
use mc_game::world::level::levelgen::structure::piece::{BlockSelector, PieceBase, STRUCTURE_PIECE_TYPES};
use mc_game::world::level::levelgen::structure::scattered_feature_piece::ScatteredFeaturePieceData;
use mc_game::world::level::levelgen::structure::{StructureManager, StructurePiece, StructurePieceSerializationContext, StructurePieceType};
use mc_game::world::level::levelgen::GenEnv;
use mc_core::pos::{BlockPos, ChunkPos};
use mc_nbt::CompoundTag;
use mc_world::status::ChunkStatus;

fn int(s: &str) -> i32 {
    s.parse().unwrap_or_else(|_| panic!("int {s}"))
}

fn ints(t: &[&str], from: usize) -> [i32; 6] {
    std::array::from_fn(|k| int(t[from + k]))
}

fn dir(s: &str) -> Option<Direction> {
    (s != "null").then(|| Direction::by_name(s).unwrap_or_else(|| panic!("direction {s}")))
}

fn piece_type() -> &'static StructurePieceType {
    STRUCTURE_PIECE_TYPES.iter().find(|t| t.id == "msroom").expect("mineshaft room piece type")
}

struct TestPiece(PieceBase);

impl StructurePiece for TestPiece {
    fn base(&self) -> &PieceBase {
        &self.0
    }
    fn base_mut(&mut self) -> &mut PieceBase {
        &mut self.0
    }
    fn add_additional_save_data(&self, _: &StructurePieceSerializationContext<'_>, _: &mut CompoundTag) {}
    fn post_process(&mut self, _: &mut dyn mc_game::world::level::levelgen::WorldGenLevel, _: &StructureManager, _: &GenEnv, _: &mut dyn RandomSource, _: &BoundingBox, _: ChunkPos, _: BlockPos) {}
}

/// The oracle's anonymous selector: `edge ? (nextFloat < 0.3 ? a : b) : (nextInt(4) == 0 ? a : b)`.
struct TwoStateSelector {
    a: BlockState,
    b: BlockState,
    next: BlockState,
}

impl BlockSelector for TwoStateSelector {
    fn next(&mut self, random: &mut dyn RandomSource, _: i32, _: i32, _: i32, is_edge: bool) {
        self.next = if is_edge {
            if random.next_float() < 0.3 { self.a } else { self.b }
        } else if random.next_int_bounded(4) == 0 {
            self.a
        } else {
            self.b
        };
    }
    fn get_next(&self) -> BlockState {
        self.next
    }
}

/// `describe()` of the oracle's `TestPiece` (Java enum `toString`s are the upper-case constant names).
fn describe(p: &TestPiece) -> String {
    let rotation = match p.get_rotation() {
        Rotation::None => "NONE",
        Rotation::Clockwise90 => "CLOCKWISE_90",
        Rotation::Clockwise180 => "CLOCKWISE_180",
        Rotation::Counterclockwise90 => "COUNTERCLOCKWISE_90",
    };
    let mirror = match p.get_mirror() {
        Mirror::None => "NONE",
        Mirror::LeftRight => "LEFT_RIGHT",
        Mirror::FrontBack => "FRONT_BACK",
    };
    format!("{} {} {rotation} {mirror}", p.get_bounding_box(), p.get_orientation().map_or("null".to_string(), |d| d.to_string()))
}

struct Ctx {
    random: WorldgenRandom,
    chunk_bb: BoundingBox,
    piece: TestPiece,
    scattered: ScatteredFeaturePieceData,
}

fn exec(c: &mut Ctx, level: &mut GenLevel<'_>, op: &str) -> String {
    let t: Vec<&str> = op.split(' ').collect();
    let state = |i: usize| parse_state(t[i]);
    let flag = |i: usize| t[i] == "true";
    let p = &c.piece;
    let bb = &c.chunk_bb;
    match t[0] {
        "chunkbb" => {
            let v = ints(&t, 1);
            c.chunk_bb = BoundingBox::new(v[0], v[1], v[2], v[3], v[4], v[5]);
            "ok".into()
        }
        "piece" => {
            let v = ints(&t, 2);
            c.piece = TestPiece(PieceBase::new(piece_type(), 3, BoundingBox::new(v[0], v[1], v[2], v[3], v[4], v[5])));
            c.piece.set_orientation(dir(t[1]));
            describe(&c.piece)
        }
        "scattered" => {
            c.scattered = ScatteredFeaturePieceData::new(piece_type(), int(t[1]), int(t[2]), int(t[3]), int(t[4]), int(t[5]), int(t[6]), dir(t[7]).expect("direction"));
            format!("{} {}", c.scattered.base.bounding_box, c.scattered.height_position)
        }
        "avg" => {
            let b = c.scattered.update_average_ground_height(&*level, bb, int(t[1]));
            format!("{b} {} {}", c.scattered.base.bounding_box, c.scattered.height_position)
        }
        "low" => {
            let b = c.scattered.update_height_position_to_lowest_ground_height(&*level, int(t[1]));
            format!("{b} {} {}", c.scattered.base.bounding_box, c.scattered.height_position)
        }
        "place" => {
            p.place_block(level, state(4), int(t[1]), int(t[2]), int(t[3]), bb);
            "ok".into()
        }
        "get" => state_string(p.get_block(&*level, int(t[1]), int(t[2]), int(t[3]), bb)),
        "interior" => p.is_interior(&*level, int(t[1]), int(t[2]), int(t[3]), bb).to_string(),
        "box" => {
            let v = ints(&t, 1);
            p.generate_box(level, bb, v[0], v[1], v[2], v[3], v[4], v[5], state(7), state(8), flag(9));
            "ok".into()
        }
        "air" => {
            let v = ints(&t, 1);
            p.generate_air_box(level, bb, v[0], v[1], v[2], v[3], v[4], v[5]);
            "ok".into()
        }
        "maybebox" => {
            let v = ints(&t, 2);
            let prob: f32 = t[1].parse().expect("float");
            p.generate_maybe_box(level, bb, &mut c.random, prob, v[0], v[1], v[2], v[3], v[4], v[5], state(8), state(9), flag(10), flag(11));
            "ok".into()
        }
        "maybeblock" => {
            let prob: f32 = t[1].parse().expect("float");
            p.maybe_generate_block(level, bb, &mut c.random, prob, int(t[2]), int(t[3]), int(t[4]), state(5));
            "ok".into()
        }
        "sphere" => {
            let v = ints(&t, 1);
            p.generate_upper_half_sphere(level, bb, v[0], v[1], v[2], v[3], v[4], v[5], state(7), flag(8));
            "ok".into()
        }
        "column" => {
            p.fill_column_down(level, state(4), int(t[1]), int(t[2]), int(t[3]), bb);
            "ok".into()
        }
        "chest" => p.create_chest(level, bb, &mut c.random, int(t[1]), int(t[2]), int(t[3]), t[4]).to_string(),
        "dispenser" => p.create_dispenser(level, bb, &mut c.random, int(t[1]), int(t[2]), int(t[3]), Direction::by_name(t[4]).expect("facing"), t[5]).to_string(),
        "sel" => {
            let v = ints(&t, 1);
            let mut selector = TwoStateSelector { a: state(8), b: state(9), next: state(9) };
            p.generate_box_selector(level, bb, v[0], v[1], v[2], v[3], v[4], v[5], flag(7), &mut c.random, &mut selector);
            "ok".into()
        }
        "move" => {
            c.piece.move_by(int(t[1]), int(t[2]), int(t[3]));
            describe(&c.piece)
        }
        "rand" => c.random.next_long().to_string(),
        other => panic!("unknown op {other}"),
    }
}

#[test]
fn structure_piece_helpers_match_vanilla() {
    let fixture = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/structure_piece.txt")).expect("fixture present");
    let mut lines = fixture.lines();
    let (mut scenarios, mut ops, mut dump_lines) = (0, 0, 0);
    let mut failures: Vec<String> = Vec::new();
    while let Some(header) = lines.next() {
        let h: Vec<&str> = header.split(' ').collect();
        assert_eq!(h[0], "SCENARIO", "{header}");
        let (seed, cx, cz) = (h[2].parse::<i64>().unwrap(), int(h[3]), int(h[4]));
        let mut synth = SynthRegion::new(seed, cx, cz, ChunkStatus::Features, 2);
        let before = snapshot(&synth);
        let mut level = synth.level();
        let placeholder = BoundingBox::new(0, 0, 0, 0, 0, 0);
        let mut ctx = Ctx {
            random: WorldgenRandom::new(Box::new(LegacyRandomSource::new(seed ^ 0x5DEECE66D))),
            chunk_bb: BoundingBox::new(cx * 16, MIN_Y + 1, cz * 16, cx * 16 + 15, MIN_Y + HEIGHT - 1, cz * 16 + 15),
            piece: TestPiece(PieceBase::new(piece_type(), 3, placeholder)),
            scattered: ScatteredFeaturePieceData::new(piece_type(), 0, 0, 0, 1, 1, 1, Direction::North),
        };
        let mut expected_dump = Vec::new();
        while let Some(line) = lines.next() {
            if line == "END" {
                break;
            }
            if let Some(op) = line.strip_prefix("> ") {
                let want = lines.next().and_then(|l| l.strip_prefix("= ")).expect("result line");
                let got = exec(&mut ctx, &mut level, op);
                ops += 1;
                if got != want && failures.len() < 20 {
                    failures.push(format!("scenario {} op `{op}`: got `{got}`, vanilla `{want}`", h[1]));
                }
            } else if let Some(d) = line.strip_prefix("D ") {
                expected_dump.push(d.to_string());
            } else {
                panic!("bad fixture line {line}");
            }
        }
        let got_dump = dump(&mut level, &before);
        dump_lines += expected_dump.len();
        if got_dump != expected_dump {
            let first = got_dump.iter().zip(&expected_dump).position(|(a, b)| a != b).unwrap_or(got_dump.len().min(expected_dump.len()));
            failures.push(format!(
                "scenario {} dump differs at line {first}: ours `{}`, vanilla `{}` ({} vs {} lines)",
                h[1],
                got_dump.get(first).map_or("<none>", String::as_str),
                expected_dump.get(first).map_or("<none>", String::as_str),
                got_dump.len(),
                expected_dump.len()
            ));
        }
        scenarios += 1;
    }
    assert!(failures.is_empty(), "{scenarios} scenarios, {ops} ops, {dump_lines} dump lines:\n{}", failures.join("\n"));
    assert!(scenarios == 12 && ops > 3000 && dump_lines > 1000, "fixture too small: {scenarios} scenarios, {ops} ops, {dump_lines} dump lines");
}
